var i=[{key:"interpolacion",nombre:"Interpolaci\xF3n",principio:"El modelo PASA EXACTAMENTE por todos los puntos de la tabla.",descripcion:"Con n + 1 puntos se construye un polinomio \xFAnico de grado \u2264 n que los toca a todos. Sirve cuando los datos son exactos (tablas de laboratorio, funciones conocidas) y se quiere el valor en un punto intermedio."},{key:"ajuste",nombre:"Ajuste de curvas",principio:"El modelo NO pasa por los puntos: pasa lo m\xE1s CERCA posible.",descripcion:"Cuando los datos traen error de medici\xF3n, obligar a la curva a tocar cada punto es un error. Ac\xE1 se elige una forma (una recta) y se busca la que minimiza la suma de los errores al cuadrado. Es el m\xE9todo de los m\xEDnimos cuadrados."}],a=[{key:"lagrange",nombre:"Interpolaci\xF3n de Lagrange",ruta:"lagrange",familia:"interpolacion",idea:"Construye un polinomio que pasa por todos los puntos, como suma de bases L\u1D62(x).",formula:"P(x) = \u03A3 y\u1D62 \xB7 L\u1D62(x)",criterioTexto:"Pasa exacto por los n + 1 puntos; el error depende de la funci\xF3n real.",color:"#1b6b93"},{key:"minimos-cuadrados",nombre:"M\xEDnimos cuadrados",ruta:"minimos-cuadrados",familia:"ajuste",idea:"Ajusta una recta a datos con error, minimizando la suma de los residuos al cuadrado.",formula:"y = a\u2080 + a\u2081\xB7x",criterioTexto:"Coeficiente de determinaci\xF3n r\xB2 cercano a 1 y residuos sin patr\xF3n.",color:"#8a5a00"}],t=a.reduce((o,e)=>(o[e.key]=e,o),{});function n(o){return a.filter(e=>e.familia===o)}function r(o){return`/modulo3/tipos/${o}`}function d(o){return`${r(o.familia)}/${o.ruta}/teoria`}export{i as a,a as b,n as c,r as d,d as e};
